def is_solution_free(A):
    """
    Checks if set A contains any three elements x, y, z (possibly with repetition)
    such that x + y = z.
    """
    # Convert to list/set for O(1) lookups if performance matters, but N is small here.
    elements = list(A)

    # Optimization: if the set size is less than 1, it's trivially solution-free.
    if len(elements) == 0:
        return True

    for x in elements:
        for y in elements:
            target_z = x + y
            if target_z in A:
                # Found x + y = z
                return False
    return True

# --- Test for N = 15 ---
N15 = set(range(1, 16))

# Heuristic partition based on sum-free sets:
